var reg = map[int]chan int{}
//export progress_cb
func progress_cb(progress C.int, user unsafe.Pointer) {
  id := int(uintptr(user))
  mu.Lock()
  ch := reg[id]
  mu.Unlock()
  if ch != nil {
    ch <- int(progress)
  }
}
